CREATE TABLE hr_tasks(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),created_by uuid NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL,due_date date NOT NULL,creation_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX hr_tasks_organization_id_due_date_idx ON hr_tasks(organization_id,due_date);
CREATE TABLE hr_task_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES hr_tasks(id),employee_id uuid NOT NULL REFERENCES hr_employees(id),status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','submitted','returned','completed','cancelled')),completion_note text,submitted_at timestamptz,review_note text,rating integer CHECK(rating BETWEEN 1 AND 5),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,version integer NOT NULL DEFAULT 1,last_operation_id uuid UNIQUE,last_operation_hash text,UNIQUE(task_id,employee_id),CHECK(status<>'completed' OR rating IS NOT NULL));
CREATE INDEX hr_task_assignments_employee_id_status_idx ON hr_task_assignments(employee_id,status);
INSERT INTO permissions(code,description_ar) VALUES ('hr.tasks.manage','إنشاء وإسناد ومراجعة مهام الموظفين') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='مدير النظام' AND p.code='hr.tasks.manage' ON CONFLICT DO NOTHING;
